import { describe, expect, it } from "vitest";
import { mockDays, mockSeason, mockStage } from "../../api/mockForest";
import { FOREST_2025, FOREST_2026, FOREST_2028_SUNDAY } from "./fixtures";

// The mock layout (`api/mockForest.ts`) is a simplified copy of the Rust rules for tests and stories. The tables below were
// generated by the real `year_table`: if the two disagree, the mock is wrong, and this test fails.
describe("the mock layout equals the Rust year tables", () => {
  for (const table of [FOREST_2026, FOREST_2025, FOREST_2028_SUNDAY]) {
    it(`${table.year} ${table.firstWeekday}: columns, cells and seasons`, () => {
      const mock = mockDays(table.year, table.firstWeekday, new Map());
      expect(mock.cols).toBe(table.cols);
      expect(mock.days).toHaveLength(table.days.length);
      mock.days.forEach((day, i) => {
        const real = table.days[i];
        expect({ date: day.date, row: day.row, col: day.col, season: day.season }).toEqual({
          date: real?.date,
          row: real?.row,
          col: real?.col,
          season: real?.season,
        });
      });
    });

    it(`${table.year}: a day's stage follows the notes it has (the mock formula on the lengths Rust used is not available, so only the ends)`, () => {
      expect(table.days.filter((d) => d.notes === 0).every((d) => d.stage === 0)).toBe(true);
      expect(table.days.some((d) => d.stage === 6)).toBe(true);
    });
  }

  it("the mock stage formula keeps the anchor values of PRD §7.2", () => {
    expect(mockStage([])).toBe(0);
    expect(mockStage([1, 2])).toBe(0);
    expect(mockStage([200])).toBe(1);
    expect(mockStage(Array<number>(5).fill(200))).toBe(3);
    expect(mockStage(Array<number>(30).fill(200))).toBe(6);
    expect(mockStage(Array<number>(500).fill(5000))).toBe(6);
    expect(mockSeason(12)).toBe("winter");
    expect(mockSeason(3)).toBe("spring");
  });
});
